def bars(values,title,labels=None,ylim=None):
    v=np.asarray(values,float).ravel(); low=min(0,float(v.min())-.2);high=max(.5,float(v.max())*1.2+.2)
    return plot([-.5,len(v)-.5],ylim or [low,high],[series('bar',list(enumerate(v)),title)],title,xlabel='Entry index',ylabel='Value',title=title,xticks=list(range(len(v))))

def points(x,y,title,xlim=None,ylim=None):
    x=np.asarray(x);y=np.asarray(y)
    return plot(xlim or [float(x.min())-.5,float(x.max())+.5],ylim or [float(y.min())-.5,float(y.max())+.5],[series('scatter',list(zip(x,y)),title)],title,xlabel='x',ylabel='y',title=title)

def F(k,title,changed,why,fixed,*views):return frame('s'+str(k),title,changed,why,fixed,*views)

def curve(xs,ys,title,ylim=None):
    return plot([float(min(xs)),float(max(xs))],ylim or [min(0,float(min(ys)))-.05,max(.1,float(max(ys)))*1.15],[series('line',list(zip(xs,ys)),title)],title,xlabel='Input',ylabel='Output',title=title)


def case016(setting):
    vals=np.array([2.,10.,6.,14.]); groups=['A','B','A','B'] if setting==0 else ['A','B','A',None]
    df=pd.DataFrame({'group':groups,'value':vals},index=[40,10,30,20]);out=kit.supplied(16)(df,'group','value')
    assert out.index.equals(df.index) and np.allclose(out.group_mean,[4,12,4,12] if setting==0 else [4,10,4,14])
    rows=[[str(i),str(g),num(v)] for i,g,v in zip(df.index,groups,vals)]
    counts=df.groupby('group',dropna=False).value.agg(['sum','count']);means=counts['sum']/counts['count']
    return [F(0,'Keep row identity','The row labels are 40, 10, 30, 20. They are deliberately unsorted.','An index label identifies a row; it does not tell pandas to sort that row.','Four input rows.',grid(rows,col_labels=['index','group','value'],title='Original frame')),
    F(1,'Collect each group','Values 2 and 6 belong to A. Other values form the remaining groups.','A group is a set of rows with the same key. dropna=False gives missing keys their own group.','The original row order.',grid([[str(i),num(r['sum']),num(r['count'])] for i,r in counts.iterrows()],col_labels=['group','sum','count'],title='Group statistics')),
    F(2,'Compute one mean per group',f'The means are {vec(means)}.','Each group mean is its sum divided by its count.','The original values are unchanged.',bars(means,'Mean for each group'),equation(r'\mu_g=\frac{\sum_{i:g_i=g}x_i}{n_g}')),
    F(3,'Map each mean back',f'The new column is {vec(out.group_mean)}.','transform returns one value for every original row, aligned to the original index.','Input row order and index.',grid([r+[num(m)] for r,m in zip(rows,out.group_mean)],col_labels=['index','group','value','group_mean'],title='Result in original row order'))]

def case017(setting):
    left=pd.DataFrame({'key':['B','A','B','C'],'amount':[7,2,9,1]});right=pd.DataFrame({'key':['A','B'],'rate':[10,20]})
    if setting: right=pd.concat([right,pd.DataFrame({'key':['B'],'rate':[30]})],ignore_index=True)
    valid=setting==0
    if valid:
        out=kit.supplied(17)(left,right,'key'); assert out.key.tolist()==left.key.tolist() and len(out)==4 and pd.isna(out.rate.iloc[-1])
    else:
        try:kit.supplied(17)(left,right,'key');raise AssertionError('duplicate key accepted')
        except pd.errors.MergeError:pass
    g=graph([node('l0',70,60,'B','amount 7'),node('l1',70,140,'A','amount 2'),node('l2',70,220,'B','amount 9'),node('ra',420,90,'A','rate 10'),node('rb',420,190,'B','rate 20')],[edge('l0','rb'),edge('l1','ra'),edge('l2','rb')],'Two left B rows share one right B lookup.',width=560,height=290,node_w=115,node_h=48)
    return [F(0,'Read the two tables','The left side contains repeated keys; the right side is a lookup table.','A left join keeps every left row, including an unmatched key.','Left order B, A, B, C.',grid(left.values.tolist(),col_labels=list(left.columns),title='Left rows'),grid(right.values.tolist(),col_labels=list(right.columns),title='Right lookup')),
    F(1,'Follow equal keys','Both left B rows look up the same B record.','Many left rows can map to one right record without multiplying the row count.','The join compares keys, not row positions.',g),
    F(2,'Check the right-side contract','The right B key occurs twice.' if setting else 'Each right key occurs once.','validate="many_to_one" rejects duplicates before an accidental Cartesian expansion.' if setting else 'Right uniqueness ensures at most one match per left row.','Repeated left keys are allowed.',bars([1,2 if setting else 1],'Right-side counts for A and B')),
    F(3,'Return rows or reject input','The operation raises MergeError.' if setting else 'The result has rates 20, 10, 20, missing.','Two right B matches would multiply each left B row; the supplied function deliberately refuses that result.' if setting else 'Unmatched C stays in the result with a missing rate.','No aggregation is performed.',text('Invalid example: repair by making right-side keys unique before joining.') if setting else grid(out.fillna('missing').values.tolist(),col_labels=list(out.columns),title='Left join result'),g)]

def case027(setting):
    original=np.arange(6)+setting*10;a,b=kit.supplied(27)(original);assert np.array_equal(a[::2],[-1]*3) and np.array_equal(b,original)
    nodes=[node('a',95,60,'array a',vec(original)),node('view',95,170,'a[::2]','shared memory'),node('b',415,60,'array b',vec(original)),node('copy',415,170,'b[[0,2,4]]','new memory')]
    g=graph(nodes,[edge('view','a','writes reach a'),edge('b','copy','values copied')],'Slice aliases a; fancy-indexed result owns separate storage.',width=560,height=240,node_w=170,node_h=54)
    return [F(0,'Make two independent inputs',f'Both a and b start as {vec(original)}.','The function first copies the caller’s array so this demonstration does not mutate the caller.','The original input.',matrix(np.vstack([original,original]),row_labels=['a','b'],title='Before indexing')),
    F(1,'Take a slice and an indexed copy','The same positions 0, 2, 4 are selected in both branches.','Basic slicing produces a view; integer-array indexing produces a copy.','The selected values initially match.',g),
    F(2,'Write through the slice',f'a becomes {vec(a)}.','The slice points into a’s buffer, so writing -1 reaches the source positions.','b remains untouched.',matrix(np.vstack([a,original]),row_labels=['a','b'],title='After writing through view')),
    F(3,'Write into the indexed copy',f'b remains {vec(b)}.','The temporary fancy-indexed copy changes, but its original buffer does not.','The caller’s input also remains unchanged.',g,matrix(np.vstack([a,b]),row_labels=['returned a','returned b'],title='Returned arrays'))]

def case054(setting):
    import torch
    x=torch.tensor([-2.,1.,3.],requires_grad=True,dtype=torch.float64);g=torch.tensor([1.,2.,-1.]) if setting==0 else torch.tensor([0.,1.,4.]);y=kit.supplied(54)(x);y.backward(g);expected=2*x.detach()*g;assert torch.allclose(x.grad,expected)
    nodes=[node('x',80,120,'x','input'),node('square',260,120,'square','local slope 2x'),node('loss',450,120,'upstream','gradient g')]
    return [F(0,'Evaluate the square','Inputs are -2, 1, 3; outputs are 4, 1, 9.','Forward computes values, not the final gradient.','The saved input values.',matrix([x.detach().numpy(),y.detach().numpy()],row_labels=['x','x²'],title='Forward values')),
    F(1,'Save the needed information','The backward method needs x to compute 2x.','Saving through ctx.save_for_backward lets autograd manage the tensor lifetime.','The operator is still elementwise.',graph(nodes,[edge('x','square'),edge('square','loss')],'Forward square operation.',width=560,height=240,node_w=130)),
    F(2,'Receive the upstream gradient',f'g = {vec(g)} arrives from later operations.','The local derivative alone cannot describe the complete loss. Chain-rule multiplication carries the later dependence.','Local derivative 2x.',matrix([2*x.detach().numpy(),g.numpy()],row_labels=['local 2x','upstream g'],title='Two factors in the chain rule')),
    F(3,'Multiply both factors',f'The returned input gradient is {vec(x.grad)}.','Each input contributes 2*x*g to the loss derivative. An upstream zero must produce zero here.','No parameter update is performed by backward.',bars(x.grad.numpy(),'Gradient with respect to x'),equation(r'\frac{\partial L}{\partial x_i}=\frac{\partial L}{\partial y_i}\,2x_i'))]

def case057(setting):
    import torch
    from torch.utils.checkpoint import checkpoint
    torch.manual_seed(11);x=torch.tensor([1.,2.,3.],requires_grad=True)
    def block(v):return torch.sin(v)*torch.sigmoid(v)
    y=kit.supplied(57)(block,x);y.sum().backward();actual=x.grad.clone()
    z=x.detach().clone().requires_grad_();block(z).sum().backward();assert torch.allclose(actual,z.grad)
    n=6;stored=np.array([1]*n if setting==0 else [1,0,0,1,0,0]);calls=np.array([1]*n if setting==0 else [1,2,2,1,2,2])
    # storage bars are an explicit scheduling illustration, not measured PyTorch allocation.
    nodes=[node(str(i),50+i*90,110,f'block {i+1}', 'save' if stored[i] else 'recompute') for i in range(n)]
    g=graph(nodes,[edge(str(i),str(i+1)) for i in range(n-1)],'Illustrative six-block chain with selected saved boundaries.',width=590,height=210,node_w=78,node_h=50)
    return [F(0,'Build the forward chain','Six conceptual blocks pass activations from left to right.','Backward needs information about intermediate values to evaluate derivatives.','The function and its input.',g),
    F(1,'Choose saved boundaries','All block outputs are retained.' if setting==0 else 'Only the illustrated boundary outputs are retained.','Checkpointing can discard internal saved tensors and recompute them when needed.','This diagram is a scheduling model, not a byte-level memory measurement.',bars(stored,'Illustrative retained activations',ylim=[0,1.4])),
    F(2,'Recompute during backward','Each block is evaluated once.' if setting==0 else 'Internal blocks are evaluated again in this simplified schedule.','The compute cost buys lower saved-activation storage. Actual non-reentrant early stopping can avoid some recomputation.','Weights and random choices must be consistent across the two evaluations.',bars(calls,'Illustrative forward evaluation counts',ylim=[0,2.5])),
    F(3,'Check the derivative',f'For sin(x)*sigmoid(x), the gradient is {vec(actual)}.','Checkpointed and ordinary execution were compared with PyTorch on this deterministic example.','The gradient must match even when storage strategy changes.',matrix([actual.numpy(),z.grad.numpy()],row_labels=['checkpoint','ordinary'],title='Actual checked gradients'))]

def case066(setting):
    a=np.array([[4.,1.],[1.,3.]]) if setting==0 else np.array([[10.,1.],[1.,2.]]);b=np.array([1.,2.]);x=np.zeros(2);r=b.copy();p=r.copy();states=[x.copy()];res=[np.linalg.norm(r)]
    fs=[]
    for n in range(2):
        alpha=(r@r)/(p@a@p);newx=x+alpha*p;newr=r-alpha*a@p;beta=(newr@newr)/(r@r);p=newr+beta*p;x,r=newx,newr;states.append(x.copy());res.append(np.linalg.norm(r))
    direct=np.linalg.solve(a,b);actual=kit.supplied(66,'conjugate_gradient')(a,b,2);assert np.allclose(actual,direct) and np.allclose(x,direct)
    fixed='The same symmetric positive-definite A and b.'
    for k in range(4):
        idx=min(k,2);path=np.array(states[:idx+1]);v=plot([-.3,1.2],[-.2,1.3],[series('line',path.tolist(),'CG path'),series('scatter',[direct.tolist()],'Exact solution')],'Two CG search steps end at the linear-system solution.',xlabel='x₀',ylabel='x₁',title='Solution-space path')
        fs.append(F(k,['Begin at zero','Search along the residual','Use a conjugate direction','Verify the linear system'][k],f'x = {vec(states[idx])}; residual norm = {num(res[idx])}.',['Residual r=b−Ax measures how far the current candidate misses the target.','The step length minimizes the quadratic along the current search direction.','The next direction includes a correction that preserves A-conjugacy.','The final residual is approximately zero; compare against a direct solver.'][k],fixed,v,matrix(a,title='A'),matrix(b,title='b')))
    return fs

def case077(setting):
    m=np.array([[3.,1.],[1.,3.]]);u,s,vh=np.linalg.svd(m);rank=setting+1;approx=kit.supplied(77)(m,rank);assert np.allclose(approx,(u[:,:rank]*s[:rank])@vh[:rank]);error=np.linalg.norm(m-approx);assert np.isclose(error,np.sqrt(np.sum(s[rank:]**2)))
    return [F(0,'Read the matrix','The matrix is [[3,1],[1,3]].','Each singular component is a rank-one outer product.','The original matrix.',matrix(m,title='Original matrix')),
    F(1,'Measure component strengths',f'The singular values are {vec(s)}.','The largest singular value carries the strongest matrix action.','The left and right singular directions are orthonormal.',bars(s,'Singular values')),
    F(2,'Keep the largest components',f'Keep rank {rank}; reconstruct {rank} outer products.','Truncation discards the weakest singular components first.','Matrix dimensions remain 2 × 2.',matrix(approx,title='Reconstructed matrix'),equation(r'A_r=\sum_{j=1}^{r}\sigma_j u_jv_j^T')),
    F(3,'Inspect the discarded information',f'Frobenius error = {num(error)}.','The squared error equals the sum of squared discarded singular values.','Rank two reconstructs this example exactly.',matrix(m-approx,title='Residual matrix'),bars([np.linalg.norm(m),np.linalg.norm(approx),error],'Original norm, retained norm, error'))]

