        fs.append(F(k,'Prior belief' if k==0 else f'Observe trial {k}',f'alpha={pa:g}, beta={pb:g}; posterior mean={num(mean)}, variance={num(var)}.','Success adds one to alpha; failure adds one to beta. A stronger prior moves less after one observation.','The unknown success probability lies between zero and one.',curve(xs,density,'Posterior density',ylim=[0,5]),tokens(['success' if z else 'failure' for z in obs[:k]] or ['no observations'],title='Evidence so far')))
