def case100(setting):
    p=np.array([0.,0.]);q=np.array([1.+setting,0.]);cp=np.diag([1.,2.]);cq=np.diag([2.,1.]);inv=np.linalg.inv(cq);terms=[np.log(np.linalg.det(cq)/np.linalg.det(cp)),-2.,(p-q)@inv@(p-q),np.trace(inv@cp)];actual=kit.supplied(100,'multivariate_kl_divergence')(p,cp,q,cq);assert np.isclose(actual,.5*sum(terms));assert abs(kit.supplied(100,'multivariate_kl_divergence')(p,cp,p,cp))<1e-12
    angle=np.linspace(0,2*np.pi,100);ellp=(np.sqrt(np.diag(cp))[:,None]*np.array([np.cos(angle),np.sin(angle)])).T+p;ellq=(np.sqrt(np.diag(cq))[:,None]*np.array([np.cos(angle),np.sin(angle)])).T+q
    v=plot([-2,5],[-2,2],[series('line',ellp.tolist(),'P contour'),series('line',ellq.tolist(),'Q contour')],'One-standard-deviation Gaussian contours.',xlabel='feature 1',ylabel='feature 2',title='Same area, different geometry')
    return [F(0,'Compare two distributions',f'P has mean {vec(p)}; Q has mean {vec(q)}.','A Gaussian is specified by a mean vector and a positive-definite covariance matrix.','Both distributions have dimension two.',v),
    F(1,'Measure mean displacement',f'The mean term is {num(terms[2])}.','Q’s inverse covariance weights displacement: movement in a narrow Q direction costs more.','The covariance matrices.',v,bars([terms[2]],'Mahalanobis mean term')),
    F(2,'Account for shape and volume',f'Trace={num(terms[3])}; log determinant ratio={num(terms[0])}; dimension correction=-2.','The trace compares spreads; the determinant ratio compares volume. The dimension correction makes identical Gaussians yield zero.','Mean displacement term.',bars(terms,'log-volume, −dimension, mean, trace')),
    F(3,'Combine the terms',f'KL(P || Q) = {num(actual)} nats.','Add all four terms and multiply by one half. This is directed: swapping P and Q generally changes the answer.','The natural logarithm sets units to nats.',equation(r'D_{KL}(P\Vert Q)=\tfrac12[\log\frac{|\Sigma_Q|}{|\Sigma_P|}-d+\Delta^T\Sigma_Q^{-1}\Delta+\mathrm{tr}(\Sigma_Q^{-1}\Sigma_P)]'),v)]

