def static_figure(frames, title):
    """Render two topic-specific checked states as an accessible SVG overview."""
    fig,axes=plt.subplots(1,2,figsize=(12,4.2),facecolor='white')
    for ax,f in zip(axes,[frames[0],frames[-1]]):
        candidates=[v for v in f['views'] if v['type'] in ('plot','graph','grid','tokens')]
        v=candidates[0]
        ax.set_facecolor('#f3f7fa');ax.set_title(f['title'],fontsize=12,color='#14223e',pad=15)
        if v['type']=='plot':
            for n,s in enumerate(v['series']):
                pts=np.array(s['points']);color=COLORS[n%4]
                if s['kind']=='scatter':ax.scatter(pts[:,0],pts[:,1],color=color,s=36,label=s['label'])
                elif s['kind']=='bar':ax.bar(pts[:,0],pts[:,1],color=color,width=.55,label=s['label'])
                elif s['kind']=='step':ax.step(pts[:,0],pts[:,1],color=color,where='post',label=s['label'],linewidth=2)
                else:ax.plot(pts[:,0],pts[:,1],color=color,label=s['label'],linewidth=2)
            ax.set_xlim(v['x']);ax.set_ylim(v['y']);ax.set_xlabel(v.get('xlabel',''));ax.set_ylabel(v.get('ylabel',''));ax.grid(alpha=.15);ax.legend(fontsize=8,loc='best')
        elif v['type']=='graph':
            ns={n['id']:n for n in v['nodes']};ax.set_xlim(0,v.get('width',560));ax.set_ylim(v.get('height',260),0);ax.axis('off')
            for e in v['edges']:
                a,b=ns[e['from']],ns[e['to']];ax.annotate('',xy=(b['x'],b['y']),xytext=(a['x'],a['y']),arrowprops={'arrowstyle':'->','color':'#8da0af','lw':1.5},zorder=1)
            for n in ns.values():ax.text(n['x'],n['y'],n['label']+'\n'+n.get('sub',''),ha='center',va='center',fontsize=8,color='#14223e',bbox={'boxstyle':'round,pad=.5','facecolor':'#d9efeb','edgecolor':'#13877e'},zorder=3)
        elif v['type']=='grid':
            cells=[[str(c.get('t','')) if isinstance(c,dict) else str(c) for c in row] for row in v['cells']]
            ax.axis('off');tab=ax.table(cellText=cells,colLabels=v.get('col_labels'),rowLabels=v.get('row_labels'),loc='center',cellLoc='center');tab.auto_set_font_size(False);tab.set_fontsize(9);tab.scale(1,1.7)
            for (r,c),t in tab.get_celld().items():t.set_edgecolor('#c9d9df');t.set_facecolor('#e6f3ef' if r%2 else '#f3f7fa')
        else:
            ax.axis('off');items=v['items'];n=len(items)
            for i,it in enumerate(items):ax.text(.05,.9-i*.8/max(n,1),it['t']+(' — '+it['sub'] if it.get('sub') else ''),fontsize=10,color=COLORS[i%4],transform=ax.transAxes)
    fig.suptitle(title,fontsize=15,color='#14223e',y=1.01);fig.tight_layout();return fig


def selectable_trace(fn):
    """Expose numerical entries and graph nodes to the shared selection inspector."""
    def wrapped(setting):
        frames=[copy.deepcopy(f) for f in fn(setting)]
        for f in frames:
            all_explanations={}
            for vi,v in enumerate(f['views']):
                explanations={}
                if v['type']=='grid':
                    for ri,row in enumerate(v['cells']):
                        for ci,c in enumerate(row):
                            sid=f'view-{vi}-row-{ri}-col-{ci}'
                            c['id']=sid
                            c['title']=f"{v.get('title','Array')}, row {ri}, column {ci}: {c['t']}"
                            explanations[sid]=c['title']+'. '+f['why']
                elif v['type']=='graph':
                    for n in v['nodes']:
                        n['sel']=f"view-{vi}-{n['id']}"
                        n['title']=n['label']+(': '+n['sub'] if n.get('sub') else '')
                        explanations[n['sel']]=n['title']+'. '+f['why']
                elif v['type']=='tokens':
                    for ti,t in enumerate(v['items']):
                        sid=f'view-{vi}-token-{ti}';t['id']=sid
                        explanations[sid]=t['t']+(': '+t['sub'] if t.get('sub') else '')+'. '+f['why']
                if explanations:
                    v['by_sel']=explanations
                    all_explanations.update(explanations)
            if all_explanations:
                f['views'].append(text('Select a value, token, or graph node to inspect its meaning at this step.',by_sel=all_explanations))
        return frames
    return wrapped


def build():
    articles=[]
    for n in IDS:
        info=CONTENT[n];record=kit.record(n);slug='lesson-q027-array-mutation' if n==27 else f'lesson-q{n:03d}'
        a=Article(slug,info['title'],exercises=[(n,'deep-lesson')],sources=[('Original exercise topic',record['url'])] if record.get('url') else [])
        a.p(info['prose'][0])
        a.h2('What this question asks').p(record['question'])
        a.h2('The background you need').p(info['prereq'])
        a.h2('Follow one complete computation').p(info['prose'][1])
        fn=selectable_trace(globals()[f'case{n:03d}']);frames=fn(0)
        a.figure('essence',static_figure(frames,info['title']),f"{info['title']}: {frames[0]['changed']} Then: {frames[-1]['changed']}",'Two verified stages from the worked example.',caption='The opening and final states. Use the animation below to inspect every intermediate step.')
        help=[{'step_id':f['id'],'help_type':'expanded-equation','content':f['why']+' '+f['changed']} for f in frames]
        a.demo(f'compute-{n:03d}','Change the scenario, then trace each operation',fn,params=[('setting',info['param'],info['options'])],help=help,facts=[('Displayed values follow the implemented worked example and its assertions.','tools/lessons/lessons/expanded_01_12.py; assertions run at generation')])
        a.h2('Connect the picture to the mathematics').eq(info['equation'],info['symbols']).p(info['prose'][2])
        a.h2('Mistakes and boundaries').callout('boundary',info['prose'][3],title='The boundary of this implementation')
        a.h2('Predict before revealing')
        for suffix,kind,payload in [('prediction','prediction',info['predict']),('new-case','new-case',info['new'])]:
            prompt,answer,explanation=payload
            a.check(f'q{n:03d}-{suffix}',kind,prompt,'number',answer=answer,tolerance=1e-5,explanation=expl(explanation,'Revisit the stated quantities and units. '+explanation))
        a.h2('Connect to the supplied solution')
        notes=[(kit.line_of(n,needle),needle,explanation) for needle,explanation in info['needles']]
        a.walkthrough(n,notes,title=f'Question {n:03d}: original code, explained')
        a.callout('note','The original solution is preserved. The diagrams use deliberately small examples to expose the mechanism. Passing these checks is evidence for these examples, not an exhaustive correctness proof.')
        articles.append(a)
    return articles
